// Generate the files of the docs site that are meant for coding agents (LLMs),
// following the llms.txt convention (https://llmstxt.org):
//
// - public/llms.txt: the index. What tonal is and a link to every file below.
// - public/llms-api.txt: every public function, a copy of
//   packages/tonal/llms-api.txt (generated by scripts/llms-api.mjs).
// - public/docs/<page>.md: the markdown of every docs page, next to the HTML
//   page (/docs/groups/chords/ is also at /docs/groups/chords.md).
//
// The order and titles come from content/docs (meta.json and the frontmatter
// of each page), so a new page appears here without changes. The generated
// files are gitignored. It runs before `next build` and `next dev`, after
// docs-from-readmes.mjs.
import {
  copyFileSync,
  mkdirSync,
  readdirSync,
  readFileSync,
  rmSync,
  statSync,
  writeFileSync,
} from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const SITE_URL = "https://tonaljs.github.io/tonal";

const site = join(dirname(fileURLToPath(import.meta.url)), "..");
const content = join(site, "content", "docs");
const pub = join(site, "public");
const apiFile = join(site, "..", "packages", "tonal", "llms-api.txt");

/** Split a page into its frontmatter fields and its body */
function readPage(file) {
  const text = readFileSync(file, "utf8");
  const match = text.match(/^---\n([\s\S]*?)\n---\n/);
  const fields = {};
  if (match) {
    for (const line of match[1].split("\n")) {
      const field = line.match(/^(\w+):\s*(.*)$/);
      if (field) fields[field[1]] = field[2].replace(/^["']|["']$/g, "");
    }
  }
  return { ...fields, body: match ? text.slice(match[0].length) : text };
}

const readMeta = (slug) =>
  JSON.parse(readFileSync(join(content, ...slug, "meta.json"), "utf8"));

/**
 * The pages of a folder, depth first, in the order Fumadocs shows them: the
 * `pages` of its meta.json, or its .md files sorted by name if there is none.
 */
function pagesOf(slug = []) {
  const dir = join(content, ...slug);
  const names =
    readMeta(slug).pages ??
    readdirSync(dir)
      .filter((file) => file.endsWith(".md"))
      .map((file) => file.slice(0, -3))
      .sort();
  const pages = [];
  for (const name of names) {
    if (statSync(join(dir, name), { throwIfNoEntry: false })?.isDirectory()) {
      const title = readMeta([...slug, name]).title;
      pages.push({ section: title ?? name[0].toUpperCase() + name.slice(1) });
      pages.push(...pagesOf([...slug, name]));
    } else {
      const page = readPage(join(dir, `${name}.md`));
      pages.push({ ...page, path: [...slug, name].join("/") });
    }
  }
  return pages;
}

/** Links in the pages are site-relative: make them absolute, to the .md */
function absoluteLinks(body) {
  return body
    .replace(
      /\]\((?:https:\/\/tonaljs\.github\.io\/tonal)?\/docs\/([^)#]+?)\/?(#[^)]*)?\)/g,
      (_, path, hash = "") => {
        return `](${SITE_URL}/docs/${path}.md${hash})`;
      },
    )
    .replace(/\]\(\/(?!\/)/g, `](${SITE_URL}/`);
}

const pages = pagesOf();

// the markdown of each page, with its title and description
rmSync(join(pub, "docs"), { recursive: true, force: true });
for (const page of pages) {
  if (!page.path) continue;
  const file = join(pub, "docs", `${page.path}.md`);
  mkdirSync(dirname(file), { recursive: true });
  const header = [`# ${page.title}`];
  if (page.description) header.push("", `> ${page.description}`);
  writeFileSync(
    file,
    `${header.join("\n")}\n\n${absoluteLinks(page.body).trim()}\n`,
  );
}

copyFileSync(apiFile, join(pub, "llms-api.txt"));

// the index
const lines = [];
for (const page of pages) {
  if (page.section) {
    lines.push("", `## ${page.section}`, "");
    continue;
  }
  if (page.path === "index" || page.path === "agents") continue;
  const description = page.description ? `: ${page.description}` : "";
  lines.push(
    `- [${page.title}](${SITE_URL}/docs/${page.path}.md)${description}`,
  );
}

writeFileSync(
  join(pub, "llms.txt"),
  `# tonal

> tonal is a functional music theory library for JavaScript and TypeScript:
> notes, intervals, chords, scales, modes, keys, Roman numerals, voicings and
> more. It works with musical abstractions (note names, not audio). All
> functions are pure and invalid input returns empty values instead of
> throwing.

Install with \`npm install tonal\` and import namespaces from it:
\`import { Note, Chord, Scale, Key } from "tonal"\`. Each namespace is also
published on its own as \`@tonaljs/<name>\`.

Before writing code with tonal, read the agent guide, then look up the functions
you need in the API list instead of guessing their names.

## Start here

- [Agent guide](${SITE_URL}/docs/agents.md): how tonal works, mistakes to avoid,
  which function to use for common tasks
- [API](${SITE_URL}/llms-api.txt): every public function with its signature,
  return type and a one-line description. It's also in the npm package at
  \`node_modules/tonal/llms-api.txt\`, matching the installed version
- [Getting started](${SITE_URL}/docs/index.md)

${lines.join("\n").replace(/^\n+/, "")}

## Optional

- [Source code](https://github.com/tonaljs/tonal)
- [Changelog](https://github.com/tonaljs/tonal/blob/main/docs/CHANGELOG.md)
`,
);

console.log(
  `llms: llms.txt, llms-api.txt and ${pages.filter((p) => p.path).length} .md pages`,
);
